List<Student> students =
[
    new Student("Ada", 92),
    new Student("Grace", 78),
    new Student("Linus", 85),
    new Student("Ken", 61),
    new Student("Mei", 70),
];

var honours = students
    .Where(s => s.Score >= 80)
    .OrderByDescending(s => s.Score)
    .Select(s => $"{s.Name} ({s.Score})")
    .ToList();
Console.WriteLine(string.Join(", ", honours));

var passing = from s in students
              where s.Score >= 65
              orderby s.Name
              select s.Name;
Console.WriteLine(string.Join(", ", passing));

var byBand = students.GroupBy(s => s.Score >= 80 ? "high" : "low");
foreach (var group in byBand)
{
    Console.WriteLine($"{group.Key}: {group.Count()}");
}

record Student(string Name, int Score);

